using Microsoft.AspNetCore.Mvc;

public class ReportController : Controller
{
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();
        return File(
            System.Text.Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    [HttpPost]
    public IActionResult Redirect()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return RedirectToAction("Index", "Login"); // or: Redirect("/login")
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

    private string GenerateReport() => throw new NotImplementedException();
    private void ProcessRequest() => throw new NotImplementedException();
    private void LogError(Exception ex) => throw new NotImplementedException();
}

